/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// UI builder required for validating and list partameters at initialisation
/// </summary>
public class METVendOpenItemsUIBuilder extends SysOperationAutomaticUIBuilder
{
    DialogField numOfTasks;
    DialogField recList;

}

Method.Source:
/// <summary>
/// MPJ_5046_MetpayInterfaces 05/05/2021
/// Post build maps the dialog fields to contract
/// </summary>
public void postBuild()
{
    super();

    // get references to dialog controls after creation
    numOfTasks = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METVendOpenItemsContract, getNumOfTasks));
    recList = this.bindInfo().getDialogField(this.dataContractObject(),
                                methodStr(METVendOpenItemsContract, getRecList));
}

    /// <summary>
    /// MPJ_5046_MetpayInterfaces 05/05/2021
    /// postRun allows validation and hiding of methods
    /// </summary>
    public void postRun()
    {
        super();
    
        // register overrides for form control events
        numOfTasks.registerOverrideMethod(methodstr(FormIntControl, validate),
                methodstr(METVendOpenItemsUIBuilder, validateNumOfThreads), this);

        recList.visible(false);
    }

   /// <summary>
   /// MPJ_5046_MetpayInterfaces 05/05/2021
   /// Validating number of tasks given
   /// </summary>
   /// <param name = "_numOfTasks">Number of tasks</param>
   /// <returns>true or false</returns>
   public boolean validateNumOfThreads(FormIntControl _numOfTasks)
   {
       if (_numOfTasks.value() <= 0)
       {
           error("@MET:VendOpenItemsBatchTasks");
           return false;
       }

       return true;
   }
